<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import AdminDialog from '../../AdminDialog.vue';
const props=defineProps<{company:number;journalId:number;version:number;csrf?:string;unsaved?:boolean}>(),emit=defineEmits(['ready','notice']);
const data=ref<any>(null),file=ref<File|null>(null),busy=ref(false),error=ref(''),fileKey=ref(0),removing=ref<any>(null),reason=ref('');let generation=0;useAccountingAlerts(error);
async function load(){const g=++generation;try{const r=await fetch('/accounting/api/journals/'+props.journalId+'/payment-proofs?company_id='+props.company,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);if(g===generation){data.value=d;emit('ready',!d.required||d.has_current);}}catch(e){if(g===generation){error.value=(e as Error).message;emit('ready',false);}}}
watch(()=>[props.company,props.journalId,props.version],()=>{data.value=null;file.value=null;fileKey.value++;emit('ready',false);void load();},{immediate:true});onBeforeUnmount(()=>generation++);
useAccountingLiveRefresh(()=>load(),()=>!busy.value&&!file.value);
async function upload(){if(!file.value||busy.value||props.unsaved)return;busy.value=true;error.value='';try{
 const form=new FormData();form.set('company_id',String(props.company));form.set('version',String(props.version));form.set('payment_proof',file.value);
 const r=await fetch('/accounting/api/journals/'+props.journalId+'/payment-proofs',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||''},body:form});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);file.value=null;fileKey.value++;emit('notice',d.message);await load();
}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(){if(busy.value)return;busy.value=true;error.value='';try{const r=await fetch('/accounting/api/payment-proofs/'+removing.value.id+'/remove',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify({company_id:props.company,reason:reason.value})});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);removing.value=null;emit('notice',d.message);await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section v-if="data&&data.show_on_voucher!==false" class="ac-payment-proofs ac-approval-panel"><div class="ac-proof-heading"><h3>Payment proof</h3><span v-if="data" class="ac-badge" :class="!data.required||data.has_current?'active':'inactive'">{{data.has_current?'Attached':data.required?'Required':'Optional'}}</span></div><p v-if="!data" class="muted">Loading payment proof...</p><template v-else><p class="muted">{{data.required?'Required before Judibas Finance Officer forwards the voucher and before posting. This also applies to Super Admin.':'Payment proof is optional for JV, opening, Income and Expense voucher types.'}} CEO-signed copies are managed separately.</p><p v-if="unsaved" class="ac-help">Save voucher changes before attaching payment proof.</p><div class="ac-signed-copies"><article v-for="proof in data.proofs" :key="proof.id"><div><strong>{{proof.original_name}}</strong><small>{{proof.current?'Current saved voucher':'Previous version / unavailable file'}} &middot; {{proof.uploaded_name}} &middot; {{new Date(proof.created_at).toLocaleString()}}</small></div><div class="ac-voucher-actions"><a class="button" :href="proof.url" target="_blank" rel="noopener">View proof</a><a class="button" :href="proof.url+'&download=1'">Download</a><button v-if="data.is_super_admin" type="button" class="button ac-danger" :disabled="busy" @click="removing=proof;reason=''">Remove proof</button></div></article></div><div v-if="data.can_upload" class="ac-signed-upload"><label>Receipt / payment evidence<input :key="fileKey" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" :disabled="busy||unsaved" @change="file=($event.target as HTMLInputElement).files?.[0]||null"></label><small>JPG, PNG, WebP or PDF, up to 10 MB. Changes to the saved voucher require matching proof.</small><button type="button" class="button primary" :disabled="busy||unsaved||!file" @click="upload">{{busy?'Uploading...':'Attach payment proof'}}</button></div><p v-else-if="data.required&&!data.has_current" class="ac-help">The authorised Judibas Finance Officer must attach payment proof at the confirmation stage.</p></template>
<AdminDialog v-if="removing" title="Remove payment proof" :busy="busy" @close="!busy&&(removing=null)"><form @submit.prevent="remove"><p>The file will be removed from active attachments and retained in audit history. A required voucher needs matching proof before forwarding or posting.</p><label>Reason<textarea v-model="reason" required minlength="5" maxlength="2000" rows="2"></textarea></label><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="removing=null">Cancel</button><button class="button ac-danger" :disabled="busy||reason.trim().length<5">Remove proof</button></div></form></AdminDialog></section></template>
<style scoped>.ac-proof-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.ac-proof-heading h3{margin:0}.ac-signed-upload>.button{margin-top:10px}</style>
